import useVantaHalo from "./useVantaHalo";

export default function OngoingInterview() {
  const vantaRef = useVantaHalo();

  return (
    <div ref={vantaRef} className="min-h-screen flex flex-col items-center justify-center px-6 py-16 text-center">
      <h1 className="text-3xl font-semibold text-white mb-3">Ongoing Interview</h1>
      <p className="text-white/70 leading-relaxed">
        Interview in progress. Content coming soon.
      </p>
    </div>
  );
}
